 * [Claude] drafted; Christopher checks. Song examples are only the widely documented ones.
 */
object Commentary {
    data class Rows(val function: String? = null, val where: String? = null)

    val chords: Map<String, Rows> = mapOf(
        "maj" to Rows("I, IV and V of a major key; III, VI and VII of a natural minor key.", "Everywhere."),
        "m" to Rows("ii, iii and vi of a major key; i and iv of a minor key, and v in natural minor."),
        "dim" to Rows("vii° of a major key and ii° of a minor key. Also a passing chord between chords a whole step apart (I – ♯I° – ii)."),
        "aug" to Rows("III+ of harmonic minor. Also a passing chord when a major triad's 5th rises a half step (I – I+ – vi or I6)."),
        "sus2" to Rows("The 3rd replaced by the 2nd: neither major nor minor, often left unresolved as a colour.", "Pop and rock guitar, ambient and worship pads."),
        "sus4" to Rows("The 3rd held back by the 4th, which classically falls to the 3rd on the same root (Vsus4 – V).", "Cadences in every style; rock riffs that rock between sus4 and major."),
        "5" to Rows("Root and 5th only, so neither major nor minor; it takes the quality of the key around it.", "Rock and metal rhythm guitar: it stays clear under distortion."),
        "6" to Rows("A major tonic with the 6th added in place of the 7th. Same notes as the m7 a minor third below (C6 = Am7).", "Swing-era endings, early jazz, rockabilly and surf."),
        "m6" to Rows("A minor tonic with the major 6th (the Dorian 6th). Same notes as the m7♭5 a minor third below (Cm6 = Am7♭5).", "Jazz minor tonics, bossa nova, gypsy jazz."),
        "maj7" to Rows("Imaj7 and IVmaj7 of a major key; ♭IIImaj7 and ♭VImaj7 of a minor key. The 7th sits a half step under the root.", "Jazz ballads, bossa nova, soul and neo-soul, city pop."),
        "7" to Rows("The dominant: V7 to I. Its 3rd and 7th form a tritone that closes in by half steps onto the tonic's root and 3rd. Built on another degree it points at that chord instead (V7/V, a secondary dominant). In a blues every chord can be a dominant 7th.", "Blues, rock and roll, jazz, gospel, funk."),
        "m7" to Rows("ii7 (the ii – V – I), iii7 and vi7 of a major key; i7 of a Dorian or minor groove.", "Jazz changes, funk and soul vamps, modal jazz."),
        "m7b5" to Rows("iiø7 of a minor key, leading to V7 and i (the minor ii – V); viiø7 of a major key."),
        "dim7" to Rows("vii°7 of harmonic minor, resolving to i. It divides the octave into minor thirds, so one shape belongs to four roots, and any of its notes can act as a leading tone. Also a passing chord between chords a step apart."),
        "7sus4" to Rows("A dominant with the 4th in place of the 3rd: it can resolve to V7 or stand on its own. A 9sus4 is the same sound as IV over the 5th in the bass (G9sus4 ≈ F/G).", "Modal jazz, 1970s pop and soul."),
        "9" to Rows("A dominant 7th with the natural 9th (from Mixolydian).", "Funk and soul vamps, blues, jazz."),
